package com.comandos.reservation.service;import com.comandos.core.service.UnitScopeGuard;import jakarta.persistence.EntityManager;import org.springframework.http.*;import org.springframework.stereotype.Component;import org.springframework.web.server.ResponseStatusException;
@Component public class ReservationUnitScopeGuard implements UnitScopeGuard{private final EntityManager em;public ReservationUnitScopeGuard(EntityManager em){this.em=em;}public void validateOrganizationChange(long unit,long organization){long n=em.createQuery("select count(r) from InventoryReservation r where r.unit.id=:u and r.organization.id<>:o",Long.class).setParameter("u",unit).setParameter("o",organization).getSingleResult();if(n>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"The unit has reservation history.");}}
